// The QR square printed on a class sheet (3f).
//
// SERVER ONLY: `qrcode` is a Node package and the SVG it returns is injected
// with dangerouslySetInnerHTML from the sheet's server component. That is safe
// here because
//
//   * the only thing encoded is a URL WE build (joinUrl() from
//     lib/schools/join-code.ts over our own origin and a 6-character code that
//     the 0096 check constraint limits to [BCDFGHJKLMNPQRSTVWXYZ2-9]),
//   * the markup is generated by the library, not assembled from the input, and
//   * the one caller-supplied string that does reach the markup — the
//     aria-label — is attribute-escaped below.
//
// Nothing a student or a teacher types is ever interpolated into the SVG.
//
// The fixed width/height attributes are removed so the square scales with CSS
// (the sheet sizes it in mm); the viewBox is kept, so it still scales
// correctly, and role="img" + aria-label make it announce as one picture.

import QRCode from "qrcode";

/** Minimal attribute escaping for the aria-label (the only text we add). */
function escapeAttr(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/**
 * `url` as an inline SVG string, ready for dangerouslySetInnerHTML.
 * `ariaLabel` is the picture's accessible name ("Scan to join the class").
 */
export async function qrSvg(url: string, ariaLabel = "QR code"): Promise<string> {
  const raw = await QRCode.toString(url, { type: "svg", margin: 1, errorCorrectionLevel: "M" });
  // Only the opening <svg …> tag is touched: drop width/height, add role + label.
  return raw.replace(/<svg\b([^>]*)>/, (_match, attrs: string) => {
    const kept = attrs
      .replace(/\s(?:width|height)\s*=\s*"[^"]*"/g, "")
      .replace(/\s(?:width|height)\s*=\s*'[^']*'/g, "")
      .replace(/\srole\s*=\s*"[^"]*"/g, "")
      .replace(/\saria-label\s*=\s*"[^"]*"/g, "")
      .trim();
    return `<svg ${kept} role="img" aria-label="${escapeAttr(ariaLabel)}">`;
  });
}
